/**
 * STAGE 1: SYMBOLIC REASONING GUARDRAIL (v11.4 - Clean Telemetry Base)
 * Responsibility: Perform symbolic audit and preserve the full 'Suitcase' for HITL or success logs.
 * Execution Mode: Run once for each item.
 */

// 1. RETRIEVE DATA (Loop-Safe Single-Item Syntax)
const plannerData = $json;
const triggerData = $("When Executed by Another Workflow").item.json;

// --- STATE RECOVERY (The Suitcase) ---
const order = plannerData.order_details || triggerData.order_details;
const auditRound = plannerData.audit_round || triggerData.audit_round || 1;
const isReflection = plannerData.is_reflection || triggerData.is_reflection || false;
const archetype = plannerData.problem_archetype || triggerData.problem_archetype;
const drivers = plannerData.drivers || triggerData.drivers || [];
const sopContext = plannerData.sop_context || triggerData.sop_context;
const mappedDomain = plannerData.mapped_domain || triggerData.mapped_domain || "General";

// ─── FIXED: Enforce absolute fallback to empty string base ───
const historicalRejections = plannerData.rejection_reasons_log || triggerData.rejection_reasons_log || "";

// --- 2. CRITICAL: DEFENSIVE CHECK (The "Bridge" Pattern) ---
if (plannerData.error || !order) {
    return {
        // Audit Status
        symbolic_passed: false,
        symbolic_violations: [
            plannerData.error === "Structural Failure" 
                ? "STRUCTURAL_FAILURE: The LLM produced invalid JSON and could not be audited."
                : "MISSING_DATA: No order details found for auditing."
        ],
        audit_metadata: { 
            safety_gating: "CRITICAL_FAILURE",
            error_mode: true,
            round: auditRound
        },

        // The Suitcase (Carrying forward historical and context data)
        order_details: order,
        audit_round: auditRound,
        is_reflection: isReflection,
        problem_archetype: archetype,
        mapped_domain: mappedDomain,
        drivers: drivers,
        sop_context: sopContext,

        // Keep metrics alive on structural fallback failure
        rejection_reasons_log: historicalRejections,

        // Fallback Planner Data
        planner_plan: {
            symbolic_mapping: "Unmapped",
            rationale: "N/A - Parsing Error",
            steps: [],
            communication: plannerData.raw_text || "Error retrieving communication."
        },
        context: { 
            status: order ? order["Order Status"] : "ERROR",
            order_id: order ? order["Order Id"] : "UNKNOWN"
        }
    };
}

// --- 3. REGULAR AUDIT LOGIC ---
const steps = plannerData.steps || [];
let symbolic_violations = [];
let audit_metadata = {
    payment_check: "NOT_REQUIRED",
    shipping_check: "PASSED",
    safety_gating: "ACTIVE",
    round: auditRound
};

// RULE A: PAYMENT-BEFORE-SHIPMENT (SOP Section 5)
const isPendingPayment = order["Order Status"] === "PENDING_PAYMENT";
const hasVerifyPaymentStep = steps.some(s => 
    s.action && (
        s.action.toLowerCase().includes('verify') || 
        s.action.toLowerCase().includes('payment') ||
        s.action.toLowerCase().includes('confirm')
    )
);

if (isPendingPayment) {
    audit_metadata.payment_check = "REQUIRED";
    if (!hasVerifyPaymentStep) {
        symbolic_violations.push("Violation: PENDING_PAYMENT requires explicit payment verification [SOP Section 5].");
        audit_metadata.payment_check = "FAILED";
    }
}

// --- 4. PREPARE FINAL OUTPUT (The Unified Suitcase) ---
return {
    // Audit Results
    symbolic_passed: symbolic_violations.length === 0,
    symbolic_violations: symbolic_violations,
    audit_metadata: audit_metadata,

    // The Suitcase (Context & Historical Data)
    order_details: order,
    audit_round: auditRound,
    is_reflection: isReflection,
    problem_archetype: archetype,
    mapped_domain: mappedDomain,
    drivers: drivers,
    sop_context: sopContext,

    // Secure telemetry parameters for downstream aggregator nodes
    rejection_reasons_log: historicalRejections,

    // Integrated Planner Data
    planner_plan: {
        driver: plannerData.driver || archetype,
        symbolic_mapping: plannerData.symbolic_mapping || "Unmapped",
        rationale: plannerData.rationale,
        steps: steps,
        communication: plannerData.communication,
        escalation_flag: plannerData.escalation_flag || false
    },

    // Quick Reference Context
    context: {
        order_id: order["Order Id"] || order["order_id"],
        status: order["Order Status"] || order["order_status"],
        product: order["Product Name"] || "Unknown Item"
    }
};

