/**
 * PREPARE SYMBOLIC CRITIQUE (v4.5 - Token Cleanup)
 * Responsibility: Convert symbolic violations into actionable instructions and increment the loop state.
 * Goal: Ensure the Planner has the 'SOP Evidence' to fix its logic in the next round without clearing past histories.
 * Execution Mode: Run once for each item.
 */

// 1. RETRIEVE AUDIT RESULTS (Single-Item Loop Mode)
const auditResult = $json;
const violations = auditResult.symbolic_violations || [];

// 2. THE SUITCASE RECOVERY
const order = auditResult.order_details;
const archetype = auditResult.problem_archetype;
const drivers = auditResult.drivers || [];
const sopContext = auditResult.sop_context;
const currentRound = auditResult.audit_round || 1;
const mappedDomain = auditResult.mapped_domain || "General";

// Pull historical rejections from loop context memory
const historicalRejections = auditResult.rejection_reasons_log || "";

// 3. CRITIQUE GENERATOR (Instruction Engineering)
const critiqueString = violations.length > 0
    ? violations.join('. ')
    : "The plan failed general operational compliance checks.";

const feedbackInstruction = `AI Audit Failed. Problem: ${critiqueString}. Instructions: Please revise the logic rationale and recreate the proposed_steps to fix this specific compliance issue using the provided SOP Context and SHAP Drivers.`;

// String builder to append new symbolic blockages onto history
const currentCritique = `[Round ${currentRound} - ${mappedDomain} (SYMBOLIC)]: ${critiqueString}`;
const updatedRejectionsLog = historicalRejections 
    ? `${historicalRejections} | ${currentCritique}`
    : currentCritique;

// 4. PREPARE THE LOOP PACKET
return {
    // --- Loop Control ---
    audit_verdict: "RETRY",
    audit_round: currentRound + 1, // Increment the counter for retry tracking
    is_reflection: true,
    feedback_instruction: feedbackInstruction,

    // Pack rolling history string into next loop turn memory wire
    rejection_reasons_log: updatedRejectionsLog,

    // --- The Suitcase (Carrying forward for the next Planner attempt) ---
    order_details: order,
    problem_archetype: archetype,
    mapped_domain: mappedDomain, 
    drivers: drivers,
    sop_context: sopContext,

    // --- Audit Metadata (For the Final Aggregator/Logging) ---
    planner_plan: auditResult.planner_plan,
    symbolic_critique: critiqueString,
    context: {
        // Added defensive fallback protections for dictionary spacing differences
        order_id: order ? (order["Order Id"] || order["order_id"] || "UNKNOWN") : "UNKNOWN",
        status: order ? (order["Order Status"] || order["order_status"] || "N/A") : "N/A"
    }
};

/**
 * SYMBOLIC OUTPUT AGGREGATOR (v3.8 - Clean Telemetry Integration)
 * Responsibility: Standardize the final output for the main loop, preserving the full audit trail.
 * Goal: Eliminate the static lookback trap to prevent loop round stalls on symbolic failures.
 * Execution Mode: Run once for each item.
 */

// 1. DATA RETRIEVAL (Neural + Symbolic - Loop Safe)
const inputData = $json;

// Shifted lookback anchor to Context_Multiplexer to capture the active live loop state!
const liveContext = $("When Executed by Another Workflow").item.json; 

// 2. SUITCASE RECOVERY (The Source of Truth)
const order = liveContext.order_details;
const archetype = liveContext.problem_archetype;
const drivers = liveContext.drivers || [];
const sopContext = liveContext.sop_context;
const mappedDomain = liveContext.mapped_domain || "General";
const currentRound = Number(liveContext.audit_round || 1);

// Recover historical rejections from past loop turns
const historicalRejections = liveContext.rejection_reasons_log || "";

// 3. AUDIT STATUS IDENTIFICATION
const isRetry = inputData.audit_verdict === "RETRY" || inputData.symbolic_passed === false;
const isSuccess = inputData.symbolic_passed === true && !isRetry;

// 4. VERDICT PROCESSING
if (isSuccess) {
    /**
     * BRANCH: SUCCESS SUITCASE (Pre-Approved Transaction)
     * Requirement: Provide high-fidelity logs for auto-approval.
     */
    return {
        audit_verdict: "SUCCESS",
        is_reflection: false,
        audit_round: currentRound,

        // --- Execution Data (The Plan) ---
        final_plan: inputData.planner_plan,
        order_details: order,

        // --- Compliance Metadata (For Logs) ---
        problem_archetype: archetype,
        mapped_domain: mappedDomain,
        drivers: drivers,
        sop_context: sopContext,

        // ─── FIXED: Forward completed trace text directly without placeholder text pollution ───
        rejection_reasons_log: historicalRejections || "",

        audit_metadata: inputData.audit_metadata || { safety_gating: "PASSED" },

        // --- Audit Justification ---
        message: "Plan passed symbolic validation and is cleared for automated resolution."
    };
} else {
    /**
     * BRANCH: RETRY SUITCASE (Reflexion Loop)
     * Requirement: Record exhaustion of retries and provide correction feedback.
     */

    // String builder to append new symbolic failure reasons onto running history
    const currentCritique = `[Round ${currentRound} - Symbolic]: ${inputData.symbolic_critique || inputData.reason || "Violated hard compliance constraints."}`;
    const updatedRejectionsLog = historicalRejections 
        ? `${historicalRejections} | ${currentCritique}`
        : (inputData.rejection_reasons_log || currentCritique);

    return {
        audit_verdict: "RETRY",
        is_reflection: true,

        // Progresses smoothly to Round 3, 4, etc., by using the active multiplexer state
        audit_round: Number(inputData.audit_round || currentRound + 1),

        // --- Context Persistence (The Suitcase) ---
        order_details: order,
        problem_archetype: archetype,
        mapped_domain: mappedDomain,
        drivers: drivers,
        sop_context: sopContext,

        // ─── FIXED: Forward the clean rolling tracking string base down the loop memory wire ───
        rejection_reasons_log: updatedRejectionsLog,

        // --- Feedback Loop Metadata ---
        reason: inputData.reason || "SYMBOLIC_VIOLATION",
        feedback_instruction: inputData.feedback_instruction || inputData.symbolic_critique || "Plan rejected by symbolic audit. Please revise based on SOP constraints.",
        symbolic_critique: inputData.symbolic_critique || "Audit failed hard compliance rules.",
        planner_plan: inputData.planner_plan || null
    };
}

/**
 * SEMANTIC OUTPUT AGGREGATOR (v8.8 - Cleanup Verification)
 * Responsibility: Consolidate the Symbolic PASS with the Semantic Review result without resetting loop metrics.
 * Execution Mode: Run once for each item.
 */

// 1. STATE RECOVERY (Targeted to live loop nodes)
const inputData = $json;
const liveContext = $("When Executed by Another Workflow").item.json;
const symbolicAudit = $("Symbolic_Audit_Layer").item.json;

const order = liveContext.order_details;
const archetype = liveContext.problem_archetype;
const drivers = liveContext.drivers || [];
const sopContext = liveContext.sop_context;
const currentRound = Number(liveContext.audit_round || 1); // Resolves the Round 2 bottleneck!
const mappedDomain = liveContext.mapped_domain || "General";

// Recover historical rejections from past loop turns
const historicalRejections = liveContext.rejection_reasons_log || "";

// 2. SEMANTIC PARSING
let semanticResult = { semantic_passed: false, critique: "Parsing Failure" };
try {
    const rawText = inputData.text || "";
    const start = rawText.indexOf('{');
    const end = rawText.lastIndexOf('}');
    if (start !== -1 && end !== -1) {
        semanticResult = JSON.parse(rawText.substring(start, end + 1));
    }
} catch (e) {
    semanticResult.critique = "LLM Formatting Error: The semantic reviewer failed to produce valid JSON.";
}

const success = semanticResult.semantic_passed === true;

// 3. THE RETURN
if (success) {
    return {
        audit_verdict: "SUCCESS",
        is_reflection: false,
        audit_round: currentRound,
        final_plan: symbolicAudit.planner_plan,
        order_details: order,
        problem_archetype: archetype,
        mapped_domain: mappedDomain,
        drivers: drivers,
        sop_context: sopContext,

        // ─── FIXED: Clean pass-through with no fallback string contamination ───
        rejection_reasons_log: historicalRejections || "",

        // ─── FIXED: Purged of static quality metric artifacts ───
        audit_metadata: {
            symbolic: "PASSED",
            semantic: "PASSED",
            safety_gating: "ACTIVE"
        },
        message: "Plan cleared symbolic guardrails and semantic logic review."
    };
} else {
    // String builder to join new error onto old history trail
    const currentCritique = `[Round ${currentRound} - ${mappedDomain}]: ${semanticResult.critique || "Failed semantic checks."}`;
    const updatedRejectionsLog = historicalRejections 
        ? `${historicalRejections} | ${currentCritique}`
        : currentCritique;

    return {
        audit_verdict: "RETRY",
        is_reflection: true,
        audit_round: currentRound + 1, // Progresses smoothly to Round 3, Round 4, etc.
        feedback_instruction: `SEMANTIC CRITIQUE: ${semanticResult.critique || "Plan failed semantic validation checks."}`,
        order_details: order,
        problem_archetype: archetype,
        mapped_domain: mappedDomain,
        drivers: drivers,
        sop_context: sopContext,
        planner_plan: symbolicAudit.planner_plan,
        failure_type: "SEMANTIC",

        // Pass the rolling text package forward into the loop memory wire
        rejection_reasons_log: updatedRejectionsLog,

        // ─── FIXED: Purged of static quality metric artifacts ───
        audit_metadata: {
            symbolic: "PASSED",
            semantic: "FAILED"
        }
    };
}
